"Alex Ferguson era famoso por el «secador de pelo»: broncas a gritos a centímetros de la cara del jugador.":"Alex Ferguson était célèbre pour son « sèche-cheveux » : des engueulades à pleine voix à quelques centimètres du visage du joueur.",
