"El VAR es un invento maravilloso. Lástima que lo manejen humanos, que al final son los que se equivocan.":"La VAR est une invention merveilleuse. Dommage qu'elle soit gérée par des humains, qui finissent par se tromper.",
"El VAR ha intervenido varias veces hoy. ¿Opina que mejora el fútbol?":"La VAR est intervenue plusieurs fois aujourd'hui. Pensez-vous qu'elle améliore le football ?",
