"El agente cumple su amenaza y tres jugadores se ponen tensos.":"L'agent met sa menace à exécution et trois joueurs se crispent.",
"El agente de {name} representa también a otros dos de tus jugadores. Ahora exige que su cliente cobre como los mejores, o «se lo pensarán todos».":"L'agent de {name} représente aussi deux autres de tes joueurs. Il exige maintenant que son client soit payé comme les meilleurs, sinon « ils vont tous réfléchir ».",
"El agente recula: su cliente no quiere irse. Ganas autoridad.":"L'agent recule : son client ne veut pas partir. Tu gagnes en autorité.",
"El agente se ofende y lo coloca en otro club.":"L'agent se vexe et le place dans un autre club.",
"El algoritmo recomienda jugadores que ya no existen o están retirados. Hazmerreír.":"L'algorithme recommande des joueurs qui n'existent plus ou sont retraités. Risée générale.",
