"El analista te enseña los datos del GPS: {name}, tu mejor jugador, es el que menos corre y menos presiona de todo el equipo. Teme que el resto empiece a imitarle.":"L'analyste te montre les données GPS : {name}, ton meilleur joueur, est celui qui court et presse le moins de toute l'équipe. Il craint que les autres ne se mettent à l'imiter.",
