"El balón se va fuera. Te hundes en el césped mientras tus compañeras te abrazan.":"Le ballon passe à côté. Tu t'effondres sur la pelouse pendant que tes coéquipières te prennent dans leurs bras.",
"El balón te cae muerto y no perdonas.":"Le ballon te retombe dans les pieds et tu ne pardonnes pas.",
