"El candidato gana las elecciones gracias a tu nombre. En verano tendrás su oferta sobre la mesa… y en tu club ya te llaman traidor.":"Le candidat remporte les élections grâce à ton nom. En été, tu auras son offre sur la table… et dans ton club, on te traite déjà de traître.",
"El candidato pierde y el precontrato sale a la luz. Pasas de ídolo a sospechoso.":"Le candidat perd et le précontrat éclate au grand jour. Tu passes d'idole à suspect.",
"El canterano al que aconsejaste marca su primer gol y te lo dedica.":"Le jeune que tu as conseillé marque son premier but et te le dédie.",
"El canterano al que esperaste llega por fin preparado.":"Le jeune que tu as attendu est enfin prêt.",
"El canterano nuevo te sigue a todas partes. Hoy se atreve a pedirte consejo.":"Le nouveau jeune te suit partout. Aujourd'hui, il ose te demander conseil.",
"El capitán lo arregla con un par de frases.":"Le capitaine règle ça en deux phrases.",
"El capitán reconduce la situación.":"Le capitaine reprend la situation en main.",
"El capitán se marcha y la plantilla ha votado: quieren que lleves el brazalete del {club}.":"Le capitaine s'en va et l'effectif a voté : ils veulent que tu portes le brassard de {club}.",
