"El club acepta tu salida. Tienes vía libre para escuchar ofertas.":"Le club accepte ton départ. Tu as le feu vert pour écouter les offres.",
"El club acepta tus condiciones. Te quedas y sin perder dinero.":"Le club accepte tes conditions. Tu restes sans perdre d'argent.",
"El club actúa a tiempo. Él lo acaba entendiendo.":"Le club agit à temps. Il finit par comprendre.",
"El club anuncia que dejará su estadio de siempre para estrenar otro nuevo a las afueras. La afición está dividida y todos te preguntan qué te parece.":"Le club annonce qu'il va quitter son stade historique pour en inaugurer un nouveau en périphérie. Les supporters sont divisés et tout le monde te demande ton avis.",
"El club cede. Firmas el contrato de tu vida: un 70 % más y {n} año.":"Le club cède. Tu signes le contrat de ta vie : 70 % de plus et {n} an.",
"El club cede. Firmas el contrato de tu vida: un 70 % más y {n} años.":"Le club cède. Tu signes le contrat de ta vie : 70 % de plus et {n} ans.",
