"Eso es algo que hablaremos en verano. Ahora solo importa salvar la categoría, con todos los de aquí.":"C'est un sujet dont on parlera cet été. Pour l'instant, seul le maintien compte, avec tout le monde ici.",
"Eso es cosa del entrenador. Yo no voy a decir nada.":"Ça, c'est l'affaire de l'entraîneur. Je ne dirai rien.",
"Eso es fútbol. Si no lo hubiera hecho yo, lo habría hecho otro. Pero nadie me lo recordará en diez años.":"C'est le football. Si ce n'avait pas été moi, ç'aurait été un autre. Mais personne ne s'en souviendra dans dix ans.",
"Eso es una vergüenza. Si va a ser así, mejor que cierren la liga. Los árbitros también tienen que pasar por un examen.":"C'est une honte. Si ça doit se passer comme ça, autant fermer le championnat. Les arbitres aussi devraient passer un examen.",
"Eso lo decidiré yo, cuando yo quiera y como yo quiera. Hoy toca jugar, y de lo demás hablamos después.":"C'est moi qui déciderai, quand je voudrai et comme je voudrai. Aujourd'hui, on joue, et du reste on parlera après.",
"Eso no se hace. Hay que respetar a las personas, también a los jugadores. Esto no es el espíritu del fútbol.":"Ça ne se fait pas. Il faut respecter les gens, les joueurs aussi. Ce n'est pas l'esprit du football.",
"Eso nos encantaría saberlo. Ven a vernos jugar, y si encuentras algo, me avisas.":"On adorerait le savoir. Viens nous voir jouer, et si tu trouves quelque chose, préviens-moi.",
"Eso se lo tendréis que preguntar a los árbitros.":"Ça, il faudra le demander aux arbitres.",
