"Esta es mi gente y es mi equipo. Si por defenderlos me multan, que me multen cien veces.":"Ce sont mes gens et c'est mon équipe. Si on me sanctionne pour les avoir défendus, qu'on me sanctionne cent fois.",
"Esta noche nadie de mi familia me pide nada. Hoy mando yo en casa.":"Ce soir, personne dans ma famille ne me demande rien. Aujourd'hui, c'est moi le chef à la maison.",
"Esta semana te mides al {club}, el club que te dejó marchar. Su grada lleva días cantando contra ti. ¿Cómo lo celebrarás si marcas?":"Cette semaine, tu affrontes {club}, le club qui t'a laissé partir. Sa tribune chante contre toi depuis des jours. Comment fêteras-tu si tu marques ?",
"Esta semana, todos a rematar hasta que se haga de noche.":"Cette semaine, tout le monde frappe au but jusqu'à la nuit tombée.",
