"Esto es fútbol. A veces ganas, a veces pierdes y a veces tu hermano te quita el postre. Así es.":"C'est le football. Parfois tu gagnes, parfois tu perds et parfois ton frère te pique ton dessert. C'est comme ça.",
"Esto es para quienes no creyeron y para los que sí. Y para un servidor, que lo merecía como nadie.":"C'est pour ceux qui n'y ont pas cru et pour ceux qui y ont cru. Et pour votre serviteur, qui le méritait plus que personne.",
"Esto es una MASACRE. {opp} se va a casa llorando 😭 #{club}":"C'est un CARNAGE. {opp} rentre à la maison en pleurant 😭 #{club}",
"Esto no es una dictadura. Yo he dado la cara, que otros den la suya. Pero no voy a dimitir.":"Ce n'est pas une dictature. Moi, j'ai assumé, que les autres assument aussi. Mais je ne démissionnerai pas.",
"Estonia":"Estonie",
"Estos son tus jugadores. Toca cualquier nombre para cambiarlo, o genera otra plantilla si no te convence.":"Voici tes joueurs. Touche un nom pour le changer, ou génère un autre effectif si celui-ci ne te convainc pas.",
"Estoy bien. Es solo un golpe. Mañana me hacen pruebas, pero si dependiera de mí, jugaba el domingo con una pierna.":"Je vais bien. Ce n'est qu'un coup. On me fait des examens demain, mais si ça ne tenait qu'à moi, je jouerais dimanche sur une jambe.",
"Estoy centrado en recuperarme. Lo demás es ruido. Y yo, con las muletas, hago mucho ruido propio.":"Je suis concentré sur ma récupération. Le reste, c'est du bruit. Et moi, avec mes béquilles, je fais déjà assez de bruit.",
"Estoy en racha y quiero más. Que se preparen los porteros.":"Je suis en forme et j'en veux plus. Que les gardiens se préparent.",
"Estoy guardando lo mejor para cuando más se necesite.":"Je garde le meilleur pour quand on en aura le plus besoin.",
"Estoy trabajando las salidas y los balones aéreos con el preparador. Se va a notar.":"Je travaille les sorties et les ballons aériens avec l'entraîneur des gardiens. Ça va se voir.",
