"Está sucio":"Est sale",
"Estáis en la pelea por el título y todo el mundo quiere oíros.":"Vous êtes dans la course au titre et tout le monde veut vous entendre.",
"Estáis en la recta final de la {cup}. El míster te avisa: si llegáis a los penaltis, te cambiará por el portero suplente, que es un especialista.":"Vous êtes dans la dernière ligne droite de la {cup}. L'entraîneur te prévient : si vous allez aux tirs au but, il te remplacera par le gardien remplaçant, un spécialiste.",
"Estáis justo por encima del descenso, empatados a puntos. ¿Os preocupa mirar hacia abajo?":"Vous êtes juste au-dessus de la zone rouge, à égalité de points. Ça vous inquiète de regarder vers le bas ?",
"Estáis {pos}º, en descenso y a {gap} de la salvación. ¿Temes por la categoría?":"Vous êtes {pos}e, relégables et à {gap} du maintien. Tu crains la relégation ?",
"Estáis {pos}º, en descenso, aunque empatados con quien marca la salvación. ¿Temes por la categoría?":"Vous êtes {pos}e, relégables, mais à égalité avec le premier non-relégable. Tu crains la relégation ?",
"Estáis {pos}º, en puestos de ascenso, con {gap} de margen sobre el {rival}. ¿Firmáis subir ya?":"Vous êtes {pos}e, en position de montée, avec {gap} d'avance sur {rival}. Vous signez pour monter tout de suite ?",
"Estáis {pos}º, en puestos europeos, con {gap} de margen sobre el {rival}. ¿Es Europa el objetivo?":"Vous êtes {pos}e, en places européennes, avec {gap} d'avance sur {rival}. L'Europe, c'est l'objectif ?",
"Están dejándolo todo en el campo. Esto es lo que quiero ver siempre 👏":"Ils laissent tout sur le terrain. C'est ce que je veux voir à chaque fois 👏",
"Están en puestos de descenso. ¿Tiene miedo?":"Vous êtes en zone de relégation. Avez-vous peur ?",
"Están peleando por el título de {lg}. ¿Cómo viven los jugadores la presión?":"Vous jouez le titre en {lg}. Comment les joueurs vivent-ils la pression ?",
