"Estás a punto de superar un récord histórico del {club}. La prensa no habla de otra cosa.":"Tu es sur le point de battre un record historique de {club}. La presse ne parle que de ça.",
"Estás a un gol de un récord histórico de tu selección. En el partido, tu equipo consigue un penalti y todos te miran.":"Tu es à un but d'un record historique de ta sélection. Pendant le match, ton équipe obtient un penalty et tous les regards se tournent vers toi.",
"Estás entre los finalistas al premio al mejor jugador joven del año. Parte del jurado se decide con votos de los aficionados.":"Tu fais partie des finalistes pour le prix du meilleur jeune joueur de l'année. Une partie du jury repose sur le vote des supporters.",
