"Gana el {club} {score}. Buenas noches, y que nadie se emocione, que esto es muy largo. 📻":"Le {club} gagne {score}. Bonne nuit, et que personne ne s'emballe, la saison est très longue. 📻",
"Gana el {club} {score}. Como presidente de mi equipo de la liga de streamers, tomo nota de todo 🦖":"Le {club} gagne {score}. En tant que président de mon équipe de la ligue des streamers, je prends note de tout 🦖",
