"Gana el {club} {score}. Yo, como presidente de equipo de streamers, ya me veo fichando a {name} 👑":"Le {club} gagne {score}. En tant que président d'une équipe de streamers, je me vois déjà recruter {name} 👑",
"Gana el {club}. Lo de {name} ya es otra cosa, amigos. Esto es grandeza, señorío. 🤍":"Le {club} gagne. Ce que fait {name}, c'est autre chose, mes amis. C'est de la grandeur, de la classe. 🤍",
