"Hat-trick en {comp}":"Triplé en {comp}",
"Hat-trick! The ball goes home with {name}. Lovely stuff.":"Hat-trick! The ball goes home with {name}. Lovely stuff.",
"Hay bajas y el míster te pide jugar de {pos} las próximas semanas. No es tu sitio, pero confía en ti.":"Il y a des absents et l'entraîneur te demande de jouer {pos} ces prochaines semaines. Ce n'est pas ton poste, mais il te fait confiance.",
"Hay cien equipos capaces. Y mañana, en la radio, algún ex jugador dirá que somos aburridos.":"Il y a cent équipes capables. Et demain, à la radio, un ancien joueur dira qu'on est ennuyeux.",
"Hay compañeros que tienen que dar un paso adelante. Yo el primero, pero no el único.":"Certains coéquipiers doivent passer un cap. Moi le premier, mais pas le seul.",
"Hay cosas que se están haciendo mal desde arriba, no solo en el campo.":"Il y a des choses mal faites en haut lieu, pas seulement sur le terrain.",
"Hay dinero para fichar como un grande. Ahora habrá que ganar.":"De quoi recruter comme un grand. Maintenant, il faudra gagner.",
"Hay goles que el portero lo vive como un drama. Hoy al {club} le han hecho daño. Toca levantarse. 🧤":"Il y a des buts qu'un gardien vit comme un drame. Aujourd'hui, le {club} a pris un coup. Il faut se relever. 🧤",
"Hay interés, claro. Estoy bien tratado, pero el fútbol es un negocio. Y yo, un buen activo, aun lesionado.":"Il y a de l'intérêt, bien sûr. Je suis bien traité, mais le football est un business. Et moi, je suis un bon actif, même blessé.",
"Hay jugadores que no están dando lo que se espera. Lo hablaremos dentro.":"Certains joueurs ne donnent pas ce qu'on attend d'eux. On en parlera en interne.",
"Hay partidos que se juegan por el escudo, y este era uno. ¡Gracias, afición! 🏆":"Il y a des matchs qu'on joue pour l'écusson, et celui-là en était un. Merci, les supporters ! 🏆",
"Hay problemas, como en todas las casas. Pero los resolvemos en familia, no aquí delante de las cámaras.":"Il y a des problèmes, comme dans toutes les maisons. Mais on les règle en famille, pas ici devant les caméras.",
"Hay que aceptar las decisiones. Hemos tenido ocasiones para cerrar el partido antes y no lo hicimos.":"Il faut accepter les décisions. On a eu des occasions de plier le match avant et on ne l'a pas fait.",
"Hay que reconocerlo: un triplete es un triplete. Respeto, aunque duela.":"Il faut le reconnaître : un triplé, c'est un triplé. Respect, même si ça fait mal.",
"Hay que ser realistas: estamos mal. Si me preguntan, hacen falta refuerzos. Y los quiero ya.":"Soyons réalistes : on est mal. Si on me demande, il faut des renforts. Et je les veux tout de suite.",
"Hay quien marca, y hay quien ve lo que otros no ven. ¡{name}! 👁️":"Il y a ceux qui marquent, et ceux qui voient ce que les autres ne voient pas. {name} ! 👁️",
"Hay quien no entiende el gesto y la polémica se desvía de lo importante.":"Certains ne comprennent pas le geste et la polémique s'éloigne de l'essentiel.",
"Hay quien piensa que es una excusa para unos mensajes tuyos.":"Certains pensent que c'est une excuse pour des messages de ta main.",
"Hay respeto mutuo, pero cada uno mira por su cartera. Yo la mía y ellos la suya.":"Il y a un respect mutuel, mais chacun pense à son portefeuille. Moi au mien, eux au leur.",
"Hay tensión con la directiva y acabas cediendo en parte.":"Le ton monte avec la direction et tu finis par céder en partie.",
"Hay un jugador que lo ha cambiado todo: yo. Lo digo con humildad y los datos en la mano.":"Il y a un joueur qui a tout changé : moi. Je le dis avec humilité et les stats à l'appui.",
"Hay un vestuario unido, y un periodista dividido. Desde luego no es el mío el que tiene problemas.":"Il y a un vestiaire uni et un journaliste divisé. Ce n'est certainement pas le mien qui a des problèmes.",
"Hay una actualización de Camino a la Leyenda con novedades y mejoras. Tus partidas se conservan.":"Une mise à jour de Camino a la Leyenda est disponible avec des nouveautés et des améliorations. Tes parties sont conservées.",
"Hay {n} titular más en rojo.":"Il reste {n} titulaire dans le rouge.",
"Hay {n} titulares más en rojo.":"Il reste {n} titulaires dans le rouge.",
"Haz debutar a 20 canteranos.":"Fais débuter 20 jeunes du centre de formation.",
"Haz debutar a 5 canteranos.":"Fais débuter 5 jeunes du centre.",
"Haz tres cambios tácticos en un partido en directo y gánalo.":"Fais trois changements tactiques dans un match en direct et gagne-le.",
"Hazme con todos":"Attrapez-les tous",
"He ido al vestuario equivocado del puro hábito.":"Je suis allé dans le mauvais vestiaire par pure habitude.",
"He tomado una decisión: «{choice}». Sé que no gustará a todos, pero es lo que creo mejor.":"J'ai pris une décision : « {choice} ». Je sais que ça ne plaira pas à tout le monde, mais c'est ce que je crois le mieux.",
"Hecho a sí mismo":"Self-made",
"Hecho: {n} cambio en el once.":"C'est fait : {n} changement dans le onze.",
"Hecho: {n} cambios en el once.":"C'est fait : {n} changements dans le onze.",
"Hemos cambiado el sistema. Me encanta cuando la prensa se da cuenta de que no soy un dogmático.":"On a changé de système. J'adore quand la presse se rend compte que je ne suis pas un dogmatique.",
"Hemos encontrado la fórmula: pasarlo bien. Lo mejor es que los chicos se divierten, y eso se nota.":"On a trouvé la formule : prendre du plaisir. Le mieux, c'est que les gars s'amusent, et ça se voit.",
"Hemos ganado, pero no me he divertido. Hay mucho que mejorar y mañana empiezo a trabajar.":"On a gagné, mais je ne me suis pas amusé. Il y a beaucoup à améliorer et je me remets au travail dès demain.",
"Hemos jugado bien, pero necesitamos más veneno arriba. Hablaré con los míos sobre eso. Yo el primero.":"On a bien joué, mais il nous faut plus de venin devant. J'en parlerai avec les gars. Moi le premier.",
"Hemos peleado hasta el último segundo. Ánimo, el año que viene va a ser el nuestro.":"On s'est battus jusqu'à la dernière seconde. Courage, l'année prochaine sera la nôtre.",
"Hemos perdido, pero sé que esto me hará más fuerte. Los grandes se miden cuando se caen.":"On a perdu, mais je sais que ça me rendra plus fort. Les grands se jugent quand ils tombent.",
"Hemos preparado la final con mucho detalle. Si perdemos, será por algo que ni yo podía controlar.":"On a préparé la finale dans les moindres détails. Si on perd, ce sera à cause de quelque chose que même moi je ne pouvais pas contrôler.",
"Hemos tenido suerte. Hay que decirlo: a veces ganas y no sabes por qué. Disfrutemos antes de que cambie.":"On a eu de la chance. Il faut le dire : parfois tu gagnes sans savoir pourquoi. Profitons-en avant que ça change.",
"Hemos visto la repetición cien veces. Si algún día alguien dice que no era penalti, que me llame. Le invito a un café.":"On a vu le ralenti cent fois. Si un jour quelqu'un dit qu'il n'y avait pas penalty, qu'il m'appelle. Je lui offre un café.",
"Hereda el apellido de {parent} ({title}): la afición y la prensa ya saben quién es.":"Porte le nom de {parent} ({title}) : les supporters et la presse savent déjà qui c'est.",
