"Horas antes de la gala del Balón de Oro te llega el soplo: no vas a ganar, quedarás {pos}. En el {club} proponen no viajar a París en señal de protesta.":"Quelques heures avant la cérémonie du Ballon d'Or, on te souffle l'info : tu ne gagneras pas, tu finiras {pos}. Chez {club}, on propose de ne pas aller à Paris en signe de protestation.",
"Horas de vídeo. Llegáis preparados.":"Des heures de vidéo. Vous arrivez préparés.",
