"Lesión en el isquiotibial":"Lésion aux ischio-jambiers",
"Lesión grave: ¿cómo la tratas?":"Blessure grave : comment la soigner ?",
"Lesión: {inj} ({n} semana de baja).":"Blessure : {inj} ({n} semaine d'absence).",
"Lesión: {inj} ({n} semanas de baja).":"Blessure : {inj} ({n} semaines d'absence).",
