"Mal":"Mal",
"Mal día para {name}. A todos los delanteros nos pasa. La siguiente, adentro 9️⃣":"Mauvais jour pour {name}. Ça arrive à tous les attaquants. La prochaine, c'est au fond 9️⃣",
"Mal partido, sí. Pero un tropiezo no borra nada. Se volverá, como siempre se vuelve. 🤍":"Mauvais match, oui. Mais un faux pas n'efface rien. On reviendra, comme on revient toujours. 🤍",
"Mal precedente.":"Mauvais précédent.",
"Mal rato. Gracias por tanto cariño. Ahora a recuperarme y volver más fuerte 💪🩹":"Sale moment. Merci pour tout ce soutien. Maintenant, place à la récupération pour revenir plus fort 💪🩹",
"Mal, muy mal. {name} se ha dejado ver poco y mal. Toca reaccionar.":"Mauvais, très mauvais. On a peu vu {name}, et mal. Il faut réagir.",
"Mala noche de {name}: errores y poca incidencia en el juego del {club}.":"Mauvaise soirée pour {name} : des erreurs et peu d'influence sur le jeu du {club}.",
"Mala noticia para el {club}: {name} sufre una lesión y estará de baja.":"Mauvaise nouvelle pour le {club} : {name} est blessé et sera indisponible.",
"Mala suerte. El balón no quería entrar. Hay días así. Mañana nos levantamos y sale el sol.":"Pas de chance. Le ballon ne voulait pas rentrer. Il y a des jours comme ça. Demain on se lève et le soleil brille.",
