"Norteamérica y Caribe":"Amérique du Nord et Caraïbes",
"Noruega":"Norvège",
"Nos alegramos mucho: {name} se va y respiramos tranquilos 😅":"On est ravis : {name} s'en va et on respire 😅",
"Nos han ganado de manera clara. Cualquier otra cosa sería faltar al respeto al rival y a nuestros aficionados.":"Ils nous ont battus nettement. Dire autre chose serait manquer de respect à l'adversaire et à nos supporters.",
"Nos han robado la final y todo el mundo lo ha visto.":"On nous a volé la finale et tout le monde l'a vu.",
"Nos hemos dejado dos puntos por falta de ambición. No volverá a pasar, os lo aseguro.":"On a laissé filer deux points par manque d'ambition. Ça ne se reproduira pas, je vous le garantis.",
"Nos pasaron por encima. No hay excusas. Como equipo, hoy hemos fallado a nuestra gente. Pedimos disculpas.":"Ils nous ont marché dessus. Pas d'excuses. En tant qu'équipe, on a laissé tomber nos supporters aujourd'hui. On s'excuse.",
"Nota":"Note",
"Nota media":"Note moyenne",
"Nota media de {rating} o más":"Note moyenne de {rating} ou plus",
"Nota {v}":"Note {v}",
"Notas un pinchazo en el gemelo antes del partido contra el {rival}. Los médicos dicen que con una infiltración podrías jugar.":"Tu sens une piqûre au mollet avant le match contre {rival}. Les médecins disent qu'avec une infiltration, tu pourrais jouer.",
"Notas una molestia. El médico quiere que juegues; el fisio de toda la vida te dice que pares una semana.":"Tu sens une gêne. Le médecin veut que tu joues ; ton kiné de toujours te dit de t'arrêter une semaine.",
"Novedades":"Nouveautés",
"Novedades de hoy":"Nouveautés du jour",
"Noviembre de 2002: en su vuelta al Camp Nou con el Real Madrid, Figo recibió una lluvia de objetos al sacar un córner, entre ellos una cabeza de cochinillo.":"Novembre 2002 : pour son retour au Camp Nou avec le Real Madrid, Figo a reçu une pluie d'objets en tirant un corner, dont une tête de cochon de lait.",
"Noviembre de 2005: el Santiago Bernabéu se puso en pie para aplaudir a Ronaldinho tras sus dos golazos en el 0-3 del Barcelona.":"Novembre 2005 : le Santiago Bernabéu s'est levé pour applaudir Ronaldinho après ses deux buts de classe dans la victoire 0-3 de Barcelone.",
"Noviembre de 2012: el Chelsea despidió a Roberto Di Matteo seis meses después de que ganara la Champions.":"Novembre 2012 : Chelsea a limogé Roberto Di Matteo six mois après sa victoire en Ligue des champions.",
"Noviembre de 2012: en el campo del Levante, el Barcelona llegó a jugar con once futbolistas formados en La Masia.":"Novembre 2012 : sur le terrain du Levante, Barcelone a aligné onze joueurs formés à la Masia.",
"Noviembre de 2019: tras clasificar a Gales para la Eurocopa, Gareth Bale posó con una bandera que decía «Gales. Golf. Madrid. En ese orden». En el Bernabéu no gustó nada.":"Novembre 2019 : après avoir qualifié le pays de Galles pour l'Euro, Gareth Bale a posé avec un drapeau où l'on lisait « Pays de Galles. Golf. Madrid. Dans cet ordre. » Au Bernabéu, ça n'a pas du tout plu.",
