"Nuevo dibujo, nuevas dudas… y algo más de solidez.":"Nouveau schéma, nouveaux doutes… et un peu plus de solidité.",
"Nuevo episodio de mi modo carrera: replico el fichaje de {name} por el {club}. ¿Me sale mejor que en la vida real? 📋":"Nouvel épisode de mon mode carrière : je reproduis la signature de {name} au {club}. Je fais mieux que dans la vraie vie ? 📋",
