"Nunca he dicho que sea una excusa. Pero con 0-4, hasta el árbitro tiene derecho a sentirse culpable.":"Je n'ai jamais dit que c'était une excuse. Mais à 0-4, même l'arbitre a le droit de se sentir coupable.",
