"Octubre de 2011: horas después de que unos petardos incendiaran su casa, Balotelli marcó en el derbi de Mánchester y enseñó una camiseta con el lema «Why always me?».":"Octobre 2011 : quelques heures après que des pétards ont incendié sa maison, Balotelli a marqué dans le derby de Manchester et montré un maillot avec le slogan « Why always me? ».",
"Octubre de 2024: el Real Madrid no viajó a la gala del Balón de Oro al saber que Vinícius no lo ganaría.":"Octobre 2024 : le Real Madrid n'a pas fait le déplacement à la cérémonie du Ballon d'Or en apprenant que Vinícius ne le gagnerait pas.",
