"Ojalá la ciudad lo celebre con alegría y sin excesos. El fútbol es un juego, no una guerra.":"J'espère que la ville fêtera ça dans la joie et sans excès. Le football est un jeu, pas une guerre.",
"Ojalá. Esta afición se merece una alegría así.":"J'espère. Ces supporters méritent une telle joie.",
