"Prefiere ordenar el campo y defender con la línea adelantada.":"Ils préfèrent organiser le terrain et défendre avec une ligne haute.",
"Prefiere quedarse en casa: nada de paseos.":"Préfère rester à la maison : pas de promenades.",
