"Prefieres liderar con el ejemplo sin brazalete.":"Tu préfères montrer l'exemple sans brassard.",
"Prefieres liderar sin brazalete. El seleccionador lo respeta.":"Tu préfères mener sans brassard. Le sélectionneur le respecte.",
"Prefieres no cargar más las piernas.":"Tu préfères ne pas charger davantage tes jambes.",
"Prefieres no correr. El club toma nota de tu paciencia.":"Tu préfères ne pas te précipiter. Le club prend note de ta patience.",
"Prefieres no mentir. La grada se queda con la duda.":"Tu préfères ne pas mentir. Les supporters restent dans le doute.",
"Prefieres no mezclar. Sigues a lo tuyo.":"Tu préfères ne pas mélanger. Tu restes dans ton coin.",
"Prefieres que hable el campo. Algunos fans se sienten solos.":"Tu préfères laisser parler le terrain. Certains fans se sentent abandonnés.",
"Prefieres que hable tu fútbol.":"Tu préfères que ton football parle pour toi.",
"Prefieres recuperar. El cuerpo lo agradece.":"Tu préfères récupérer. Ton corps te remercie.",
"Prefieres seguir en tu club, cerca de los tuyos. El club te lo agradece.":"Tu préfères rester dans ton club, près des tiens. Le club t'en est reconnaissant.",
"Prefieres un año más con los chavales.":"Tu préfères une année de plus avec les jeunes.",
"Prefiero no hablar. Cualquier cosa que diga me costará una multa y mi cuenta corriente no está para bromas.":"Je préfère ne pas parler. Tout ce que je dirai me vaudra une amende, et mon compte en banque n'a pas envie de rire.",
"Prefiero que hablen mis paradas.":"Je préfère que mes arrêts parlent pour moi.",
"Prefiero que me recuerden por mi nombre y por lo que gane.":"Je préfère qu'on se souvienne de moi pour mon nom et pour ce que je gagnerai.",
