"Pregúnteselo a él. Yo salí a disfrutar y a mover el balón. Lo demás, que lo arreglen los de arriba.":"Demandez-lui. Moi, je suis entré pour prendre du plaisir et faire tourner le ballon. Le reste, c'est aux chefs de s'en occuper.",
