"Puedes borrar cualquier partida desde «Cargar partida». Desinstalar la app elimina todo lo guardado en el dispositivo. Para borrar los datos publicitarios que tiene Google, restablece tu ID de publicidad o entra en myadcenter.google.com.":"Tu peux supprimer n'importe quelle partie depuis « Charger une partie ». Désinstaller l'application efface tout ce qui est enregistré sur l'appareil. Pour supprimer les données publicitaires conservées par Google, réinitialise ton identifiant publicitaire ou rends-toi sur myadcenter.google.com.",
"Puedes borrar cualquier partida desde «Cargar partida». Si borras los datos de este sitio en tu navegador, se elimina todo lo guardado. Para borrar los datos publicitarios que tiene Google, entra en myadcenter.google.com.":"Tu peux supprimer n'importe quelle sauvegarde depuis « Charger une partie ». Effacer les données de ce site dans ton navigateur supprime tout ce qui est enregistré. Pour supprimer les données publicitaires détenues par Google, va sur myadcenter.google.com.",
"Puedes compaginarlo con el {club} o dejar el club y dedicarte en exclusiva.":"Tu peux cumuler avec {club} ou quitter le club pour t'y consacrer exclusivement.",
"Puedes dejar el nombre en blanco si se le conoce por un solo nombre.":"Tu peux laisser le prénom vide s'il est connu sous un seul nom.",
"Puedes dirigir clubes de nivel {n} o menos; con más prestigio llegarán los grandes.":"Tu peux entraîner des clubs de niveau {n} ou moins ; avec plus de prestige, les grands arriveront.",
"Puedes elegir el lado con menos viento y nieve.":"Tu peux choisir le côté avec moins de vent et de neige.",
"Puedes empezar en cualquier club. Si ganas, llegarán ofertas de clubes más grandes.":"Tu peux commencer dans n'importe quel club. Si tu gagnes, des offres de plus grands clubs arriveront.",
"Puedes estudiar la lista, pero solo se ficha en verano (pretemporada) y en invierno (antes del tramo Feb–Mar).":"Tu peux étudier la liste, mais on ne recrute qu'en été (pré-saison) et en hiver (avant la période Fév–Mar).",
"Puedes jugar el primer balón en largo sin presión.":"Tu peux jouer le premier ballon long sans pression.",
"Puedes pedir el dorsal que quieras. Si lo lleva un compañero, quizá tengas que esperar a la próxima temporada.":"Tu peux demander le numéro que tu veux. Si un coéquipier le porte, tu devras peut-être attendre la saison prochaine.",
"Puedes seguir con quien ya juega al fútbol o empezar con otro hijo o hija desde la cantera.":"Tu peux continuer avec celui ou celle qui joue déjà au foot, ou commencer avec un autre enfant au centre de formation.",
"Puedes seguir en el fútbol desde el banquillo: eliges club, fichas, renuevas contratos, decides el once y cuidas la moral del vestuario.":"Tu peux rester dans le football depuis le banc : tu choisis le club, tu recrutes, tu prolonges les contrats, tu composes le onze et tu soignes le moral du vestiaire.",
"Puedes volver a dibujar o elegir la potencia":"Tu peux redessiner ou choisir la puissance",
"Puerto Rico":"Porto Rico",
"Pues habrá que ganar el domingo. Fácil de decir, ¿eh?":"Eh bien, il faudra gagner dimanche. Facile à dire, hein ?",
"Puesto":"Porté",
"Puesto {n}":"{n}e place",
"Pulsa el botón grande de abajo para avanzar al siguiente tramo de la temporada.":"Appuie sur le gros bouton en bas pour passer à la période suivante de la saison.",
"Pulsa el botón grande de abajo. El juego avanza unas semanas y se para cuando hay algo que decidir.":"Appuie sur le grand bouton en bas. Le jeu avance de quelques semaines et s'arrête quand il y a quelque chose à décider.",
"Pulsa el botón grande de abajo. La temporada avanza unas semanas y se para cuando hay algo que decidir.":"Appuie sur le grand bouton en bas. La saison avance de quelques semaines et s'arrête quand il y a quelque chose à décider.",
