"Recuperas en tu campo y ves a la portera rival casi en el centro del campo. Tienes la jugada y apenas un segundo para decidir.":"Tu récupères le ballon dans ton camp et tu vois la gardienne adverse presque au milieu du terrain. Tu as l'occasion et à peine une seconde pour décider.",
