"Se acabó el cuento. A casa, que mañana tocará aguantar a la familia del {opp}.":"Fin de l'histoire. À la maison : demain, il faudra supporter la famille qui soutient {opp}.",
"Se acabó la crisis: el equipo vuelve a sonreír.":"La crise est finie : l'équipe retrouve le sourire.",
"Se acabó. Hoy os toca callarnos a nosotros. Disfrutad, que ya os llegará 😤":"C'est fini. Aujourd'hui, c'est à vous de nous laisser parler. Profitez-en, votre tour viendra 😤",
"Se acerca el derbi contra el {opp}. ¿Qué mensaje le mandas a su afición?":"Le derby contre {opp} approche. Quel message adresses-tu à ses supporters ?",
"Se acerca el mercado de invierno":"Le mercato d'hiver arrive",
"Se acerca el partido más importante del año y notas a los jugadores agarrotados. Tienes cinco minutos antes de salir al campo.":"Le match le plus important de l'année approche et tu sens tes joueurs crispés. Tu as cinq minutes avant d'entrer sur le terrain.",
"Se acercan las elecciones a la presidencia del {giant}. Uno de los candidatos te ofrece una fortuna por firmar un precontrato: si gana, pagará tu cláusula en verano. Si se filtra, en el {club} te lo harán pagar.":"Les élections à la présidence de {giant} approchent. Un des candidats t'offre une fortune pour signer un précontrat : s'il gagne, il paiera ta clause en été. Si ça fuite, chez {club}, tu le paieras cher.",
"Se activa el protocolo y el club rival identifica al responsable.":"Le protocole est déclenché et le club adverse identifie le responsable.",
"Se aplaza. Mejor para las piernas.":"C'est reporté. Mieux pour les jambes.",
"Se aplicará al volver a entrar":"S'appliquera à la prochaine ouverture",
"Se arrastran por el campo y uno acaba con una sobrecarga.":"Ils se traînent sur le terrain et l'un d'eux finit avec une surcharge musculaire.",
"Se borrará la partida de {n} de este dispositivo y de tu cuenta. No se puede deshacer.":"La partie de {n} sera supprimée de cet appareil et de ton compte. Cette action est irréversible.",
"Se cae el {club}… {score}… ¡Qué dolor, señores! ¡Duele como pisar un lego descalzo! 😭":"Le {club} s'écroule… {score}… Quelle douleur, messieurs ! Ça fait mal comme marcher pieds nus sur un Lego ! 😭",
"Se cambia en el menú, cuando quieras.":"Ça se change dans le menu, quand tu veux.",
"Se confirma: estabas más cansado de lo que pensabas.":"C'est confirmé : tu étais plus fatigué que tu ne le pensais.",
"Se conforma de momento.":"Il s'en contente pour l'instant.",
"Se critica que sales poco a por los balones aéreos. ¿Vas a cambiar?":"On te reproche de ne pas assez sortir sur les ballons aériens. Tu vas changer ?",
"Se dan la mano, pero no se miran. El pique sigue ahí.":"Ils se serrent la main, mais sans se regarder. La brouille demeure.",
"Se desbloquea paseando":"Se débloque en promenant",
"Se despide emocionado. Tú pierdes a tu mejor apoyo.":"Il fait ses adieux, ému. Tu perds ton meilleur soutien.",
"Se dice que este será su último gran partido en el club. ¿Es así?":"On dit que ce sera votre dernier grand match au club. Est-ce le cas ?",
"Se disculpa y la relación sale reforzada.":"Il s'excuse et la relation en sort renforcée.",
"Se disculpa y te asegura prioridad. Esta vez le crees.":"Il s'excuse et t'assure que tu es sa priorité. Cette fois, tu le crois.",
"Se entienden a medias. El jugador sigue desubicado.":"Ils se comprennent à moitié. Le joueur reste perdu.",
"Se escapa el título para el {club}. Toca replantear, reconstruir y volver a intentarlo.":"Le titre échappe au {club}. Il faut repenser, reconstruire et retenter sa chance.",
"Se estrena un capítulo del documental y aparece tu bronca más dura en el vestuario, con insultos incluidos. Las redes no hablan de otra cosa.":"Un épisode du documentaire sort et montre ton plus gros coup de gueule au vestiaire, insultes comprises. Les réseaux ne parlent que de ça.",
"Se filtra la noticia y la grada se inquieta.":"La nouvelle fuite et les supporters s'inquiètent.",
"Se guarda una copia sola al empezar cada temporada.":"Une copie est enregistrée automatiquement au début de chaque saison.",
