"Se irá en verano por {fee}":"Il partira cet été pour {fee}",
"Se irá libre al acabar su contrato":"Il partira libre à la fin de son contrat",
"Se juega mucho en las próximas jornadas y nadie quiere perderse tus palabras.":"Les prochaines journées sont décisives et personne ne veut manquer tes paroles.",
"Se la dedico a mí mismo. Hay que ser egoísta para ser feliz en este oficio. Y hoy lo soy mucho.":"Je me la dédie à moi-même. Il faut être égoïste pour être heureux dans ce métier. Et aujourd'hui, je le suis beaucoup.",
"Se la lleva con los pies. Ocasión perdida.":"Il te le prend du pied. Occasion manquée.",
"Se le hace grande el partido.":"Le match est trop grand pour lui.",
"Se le nota nervioso y el grupo lo nota.":"On le sent nerveux et le groupe s'en rend compte.",
