"Sospechas de todos y el ambiente se envenena.":"Tu soupçonnes tout le monde et l'ambiance devient toxique.",
"Soy del club hasta que la lesión me deje o hasta que ellos me echen. Mientras tanto, a trabajar con la pierna mala.":"Je suis au club jusqu'à ce que la blessure me lâche ou qu'ils me mettent dehors. En attendant, au travail avec ma mauvaise jambe.",
"Soy el primero en asumirlo. Tengo que sacar paradas que ahora no saco.":"Je suis le premier à l'assumer. Je dois sortir des arrêts que je ne sors pas en ce moment.",
"Soy el que más trabaja de este vestuario. No lo digo yo, lo dice el entrenador. Pregúntenle.":"Je suis celui qui travaille le plus dans ce vestiaire. Ce n'est pas moi qui le dis, c'est l'entraîneur. Demandez-lui.",
"Soy entrenador. Tengo contrato, pero mañana puedo estar en la calle. Así es esto y no me asusta.":"Je suis entraîneur. J'ai un contrat, mais demain je peux être à la rue. C'est comme ça, et ça ne me fait pas peur.",
"Soy rico, guapo y un gran jugador. Por eso me tienen envidia. No es mi culpa.":"Je suis riche, beau et un grand joueur. C'est pour ça qu'on m'envie. Ce n'est pas ma faute.",
"Soy un trabajador del club. Hago lo que me piden y ellos hacen lo suyo. Así de sencillo.":"Je suis un employé du club. Je fais ce qu'on me demande et eux font leur part. C'est aussi simple que ça.",
