"Temas Noche, Día de partido y Retro en Accesibilidad o en el menú.":"Thèmes Nuit, Jour de match et Rétro dans Accessibilité ou dans le menu.",
"Temblor de cámara":"Tremblement de caméra",
"Temp. de míster":"Saisons coach",
"Temporada":"Saison",
"Temporada 2015/16: el Leicester, que pagaba 5000 a 1 en las casas de apuestas, ganó la Premier League.":"Saison 2015/16 : Leicester, coté à 5000 contre 1 chez les bookmakers, a remporté la Premier League.",
"Temporada a temporada":"Saison après saison",
"Temporada de cine":"Saison de cinéma",
"Temporada en el juvenil":"Saison avec les jeunes",
"Temporada histórica en {comp}":"Saison historique en {comp}",
"Temporada invicta":"Saison invaincue",
"Temporada terminada":"Saison terminée",
