"Trato hecho.":"Affaire conclue.",
"Treintaidosavos":"Trente-deuxièmes",
"Tres cambios en el descuento y el reloj vuela.":"Trois changements dans le temps additionnel et le chrono file.",
"Tres canteranos más en la plantilla.":"Trois jeunes du centre de formation de plus dans l'effectif.",
"Tres canteranos nuevos":"Trois nouveaux jeunes du centre de formation",
"Tres clubes de ligas menos potentes te ofrecen su banquillo. Gana allí y llamarán los grandes.":"Trois clubs de championnats plus modestes t'offrent leur banc. Gagne là-bas et les grands t'appelleront.",
"Tres clubes modestos quieren subirte de la cantera. Elige dónde debutar.":"Trois clubs modestes veulent te faire monter du centre de formation. Choisis où débuter.",
"Tres en raya":"Morpion",
"Tres goles de {name}. Hay jugadores que juegan al fútbol. Y otros que lo escriben. 🎙️":"Trois buts de {name}. Il y a des joueurs qui jouent au football. Et d'autres qui l'écrivent. 🎙️",
"Tres goles en un abrir y cerrar de ojos y el partido es vuestro. Noche histórica.":"Trois buts en un clin d'œil et le match est à vous. Soirée historique.",
"Tres goles hoy. ¿Siente que es el mejor delantero de {lg}?":"Triplé aujourd'hui. Vous sentez-vous le meilleur attaquant de {lg} ?",
"Tres preguntas. Cada respuesta tiene consecuencias.":"Trois questions. Chaque réponse a des conséquences.",
"Tres preguntas. Verás el efecto de cada respuesta antes de elegir.":"Trois questions. Tu verras l'effet de chaque réponse avant de choisir.",
"Tres puntos más y a seguir. Ni tan mal, ¿eh? 😏 {score}":"Trois points de plus et on continue. Pas mal, hein ? 😏 {score}",
"Tres puntos más. ¿Está satisfecho con el juego del equipo?":"Trois points de plus. Êtes-vous satisfait du jeu de l'équipe ?",
"Tres semanas libres antes de la pretemporada. ¿Cómo las aprovechas?":"Trois semaines libres avant la préparation. Comment en profites-tu ?",
"Tres semanas más de baja":"Trois semaines d'absence en plus",
"Tres. TRES. ¡¡TRES!! ¿Alguien más quiere hablar de {name}? ¿No? Pues eso 😎":"Trois. TROIS. TROIS !! Quelqu'un d'autre veut parler de {name} ? Non ? Bon 😎",
