"Tu abuela se presenta por sorpresa con comida para un mes.":"Ta grand-mère débarque par surprise avec de quoi manger pendant un mois.",
"Tu afición te adora. El estadio será una olla.":"Tes supporters t'adorent. Le stade sera un chaudron.",
"Tu agente empieza a mover tu nombre. El club no lo ve con buenos ojos.":"Ton agent commence à proposer ton nom. Le club ne voit pas ça d'un bon œil.",
"Tu agente insiste en filtrar que quieres salir para forzar una mejora de contrato.":"Ton agent insiste pour faire fuiter que tu veux partir afin d'obtenir un meilleur contrat.",
"Tu agente juega a dos bandas":"Ton agent joue double jeu",
"Tu agente quiere moverte":"Ton agent veut te faire bouger",
"Tu agente tiene dos propuestas sobre la mesa: una marca deportiva de primer nivel y una bebida energética que paga el doble.":"Ton agent a deux propositions sur la table : une grande marque de sport et une boisson énergisante qui paie le double.",
"Tu amigo de la infancia tiene problemas con su negocio y te pide 50 000 €. Te promete devolverlos.":"Ton ami d'enfance a des problèmes avec son entreprise et te demande 50 000 €. Il te promet de te les rendre.",
"Tu analista ha encontrado un patrón en el rival del domingo: deja un pasillo enorme a la espalda del lateral.":"Ton analyste a repéré une faille chez l'adversaire de dimanche : un énorme couloir dans le dos du latéral.",
"Tu analista te enseña un informe: ganáis, pero el modelo dice que los resultados tienen más de suerte que de juego. Cree que deberías cambiar el plan.":"Ton analyste te montre un rapport : vous gagnez, mais selon le modèle, les résultats doivent plus à la chance qu'au jeu. Il pense que tu devrais changer de plan.",
"Tu aniversario de boda cae en plena semana de viaje con el equipo. En casa no están contentos.":"Ton anniversaire de mariage tombe en plein déplacement avec l'équipe. À la maison, on n'est pas content.",
"Tu antiguo segundo gana su primer partido y te lo dedica.":"Ton ancien adjoint gagne son premier match et te le dédie.",
"Tu arrebato se convierte en grito de guerra para la grada.":"Ton coup de sang devient un cri de guerre pour les tribunes.",
"Tu asiento vacío es la noticia de la noche. Tu afición te apoya; el resto del mundo, no tanto.":"Ton siège vide est l'info de la soirée. Tes supporters te soutiennent ; le reste du monde, beaucoup moins.",
"Tu avatar":"Ton avatar",
"Tu ayudante prepara el vídeo.":"Ton adjoint prépare la vidéo.",
"Tu banquillo":"Ton banc",
"Tu banquillo está lleno de gente con ganas y poco protagonismo. Si alguno no ve minutos, el vestuario se resiente; si juegan todos, el once pierde equilibrio.":"Ton banc est plein de joueurs motivés mais peu utilisés. Si certains ne jouent pas, le vestiaire en souffre ; si tout le monde joue, le onze perd son équilibre.",
"Tu barrio te lo agradece con un mural.":"Ton quartier te remercie avec une fresque.",
"Tu bloqueo libera a tu compañero, que remata a placer.":"Ton écran libère ton coéquipier, qui conclut à son aise.",
"Tu bloqueo libera a un compañero, que la mete.":"Ton écran libère un coéquipier, qui la met au fond.",
"Tu buen momento te dará más fuerza para negociar.":"Ta bonne forme te donnera plus de poids pour négocier.",
"Tu camiseta no se vende":"Ton maillot n'est pas en vente",
"Tu camiseta se convierte en objeto de culto. Se agota en las tiendas.":"Ton maillot devient culte. Il est en rupture de stock dans les boutiques.",
"Tu cantera ha formado a tres chicos que piden paso. Puedes subir a uno al primer equipo; los demás seguirán su camino en otros clubes.":"Ton centre de formation a révélé trois jeunes qui frappent à la porte. Tu peux en promouvoir un en équipe première ; les autres poursuivront leur chemin dans d'autres clubs.",
