"Tu carrera te espera":"Ta carrière t'attend",
"Tu celebración del último gol se ha hecho viral y aficionados de medio mundo imitan tu pose. Una marca propone registrarla y vender camisetas con ella.":"Ta célébration du dernier but est devenue virale et des supporters du monde entier imitent ta pose. Une marque propose de la déposer et de vendre des maillots avec.",
"Tu chuleta acierta: lado correcto y parada.":"Ton antisèche est bonne : bon côté et arrêt.",
