"Tu club entra en una Superliga":"Ton club rejoint une Superligue",
"Tu club lo entiende… a regañadientes.":"Ton club comprend… à contrecœur.",
"Tu club lo estudia: quiere verte crecer.":"Ton club étudie la question : il veut te voir progresser.",
"Tu club mejora tu contrato. La grada respira aliviada.":"Ton club améliore ton contrat. Les tribunes respirent.",
