"Tu hermano se casa el mismo sábado que tenéis partido fuera de casa.":"Ton frère se marie le samedi où vous jouez à l'extérieur.",
"Tu hija acaba de fichar por la cantera del eterno rival. La prensa se ha enterado y quiere saber qué opinas.":"Ta fille vient de rejoindre le centre de formation du rival de toujours. La presse l'a appris et veut ton avis.",
