"Tu nota media en los últimos {n} partidos es de {rt}. Se habla de paradones de selección. ¿Estás en tu mejor momento?":"Ta note moyenne sur tes {n} derniers matchs est de {rt}. On parle d'arrêts dignes de la sélection. Es-tu au meilleur de ta forme ?",
"Tu nota media en los últimos {n} partidos es de {rt}. ¿Estás en tu mejor momento?":"Ta note moyenne sur tes {n} derniers matchs est de {rt}. Es-tu au meilleur de ta forme ?",
"Tu nota media en los últimos {n} partidos es de {rt}. ¿Qué te está pasando?":"Ta note moyenne sur tes {n} derniers matchs est de {rt}. Qu'est-ce qui t'arrive ?",
"Tu número será tuyo y de nadie más. Las camisetas se venden bien.":"Ton numéro sera à toi et à personne d'autre. Les maillots se vendent bien.",
"Tu oferta":"Ton offre",
"Tu ojeador avisa: el {club} deja salir a {name} por {fee}.":"Ton recruteur prévient : {club} laisse partir {name} pour {fee}.",
"Tu padre ha dejado su trabajo y quiere encargarse de tus contratos. No tiene experiencia, pero dice que nadie te va a defender como él.":"Ton père a quitté son travail et veut s'occuper de tes contrats. Il n'a aucune expérience, mais il dit que personne ne te défendra comme lui.",
"Tu padre quiere ser tu agente":"Ton père veut être ton agent",
"Tu padre se enfada un tiempo, pero lo acaba entendiendo.":"Ton père t'en veut un temps, mais il finit par comprendre.",
"Tu papel":"Ton rôle",
"Tu papel es el de mentor del grupo. Pocos minutos, mucho peso.":"Ton rôle est celui de mentor du groupe. Peu de minutes, beaucoup de poids.",
"Tu pareja es periodista y le toca entrevistarte a pie de campo justo después de un partido enorme. Todo el país está mirando.":"Ta moitié est journaliste et doit t'interviewer au bord du terrain juste après un match énorme. Tout le pays regarde.",
"Tu pareja sale de cuentas justo la semana de un partido importante. El club te deja decidir.":"Ta compagne doit accoucher la semaine même d'un grand match. Le club te laisse décider.",
"Tu pareja se pone de parto en mitad de la concentración, dos días antes de un partido clave. Estás a cientos de kilómetros.":"Ta compagne entre en travail en pleine mise au vert, deux jours avant un match capital. Tu es à des centaines de kilomètres.",
"Tu partida se guarda sola en este dispositivo. Usa el código para pasarla a otro móvil.":"Ta partie se sauvegarde toute seule sur cet appareil. Utilise le code pour la passer sur un autre mobile.",
"Tu partida se guarda sola en tu cuenta y en este dispositivo.":"Ta partie se sauvegarde toute seule sur ton compte et sur cet appareil.",
"Tu patrocinador personal compite con el del club. La marca del club te pide que dejes de aparecer con la competencia en tus redes.":"Ton sponsor personnel est concurrent de celui du club. L'équipementier du club te demande de ne plus apparaître avec la concurrence sur tes réseaux.",
