"Tu pierna mala es tu gran debilidad y los rivales lo saben. Un entrenador personal te propone dedicar medio verano a corregirla.":"Ton mauvais pied est ta grande faiblesse et les adversaires le savent. Un préparateur personnel te propose d'y consacrer la moitié de l'été.",
"Tu plan no estaba tan bien pensado. Te cargas más de lo que ganas.":"Ton plan n'était pas si bien pensé. Tu te fatigues plus que tu n'y gagnes.",
