"Tu vida personal":"Ta vie privée",
"Tu vida privada sigue siendo tuya.":"Ta vie privée reste la tienne.",
"Tu vuelo para el partido fuera de casa se cancela por una tormenta. Las alternativas: diez horas de autobús esta noche o un vuelo privado carísimo mañana a primera hora.":"Ton vol pour le match à l'extérieur est annulé à cause d'un orage. Les options : dix heures de bus cette nuit ou un vol privé hors de prix demain à la première heure.",
"Tu vídeo dando las gracias a los bomberos se hace viral y te ganas a todo el mundo.":"Ta vidéo de remerciements aux pompiers devient virale et tu séduis tout le monde.",
"Tu yo de doce años no te lo perdona.":"Ton toi de douze ans ne te le pardonne pas.",
"Tumbado detrás":"Un allongé derrière",
"Tumbarse":"Se coucher",
"Turbulencias":"Turbulences",
"Turkmenistán":"Turkménistan",
"Turquía":"Turquie",
"Tus actuaciones no han pasado desapercibidas: {country1} y {country2} te quieren en su selección. Cuando debutes en partido oficial, la elección será para siempre.":"Tes prestations n'ont pas échappé aux regards : {country1} et {country2} te veulent dans leur sélection. Quand tu débuteras en match officiel, ton choix sera définitif.",
"Tus aficionados piden tu camiseta, pero la marca del club no la pone a la venta. Hay una campaña en redes para presionar y todos esperan que digas algo.":"Tes supporters réclament ton maillot, mais l'équipementier du club ne le met pas en vente. Une campagne sur les réseaux met la pression et tout le monde attend que tu dises quelque chose.",
"Tus amigos montan un torneo de un videojuego de fútbol que empieza a las once de la noche. Mañana hay entreno a las nueve.":"Tes amis organisent un tournoi de jeu vidéo de foot qui commence à onze heures du soir. Demain, entraînement à neuf heures.",
"Tus botas nuevas salen en todas las tiendas.":"Tes nouvelles chaussures sont dans tous les magasins.",
"Tus compañeros, concentrados: «Iremos partido a partido».":"Tes coéquipiers, concentrés : « On va y aller match après match ».",
"Tus competiciones":"Tes compétitions",
"Tus competiciones salen arriba; el resto, en la lista desplegable.":"Tes compétitions apparaissent en haut ; les autres dans la liste déroulante.",
"Tus directos son un éxito y tu comunidad crece sin parar.":"Tes lives sont un succès et ta communauté grandit sans arrêt.",
"Tus informes de fichajes ya no se basan en intuiciones.":"Tes rapports de recrutement ne reposent plus sur l'intuition.",
"Tus jugadores progresan más rápido.":"Tes joueurs progressent plus vite.",
"Tus jugadores se apartan y el rival empata. El fútbol entero te aplaude.":"Tes joueurs s'écartent et l'adversaire égalise. Le monde du football t'applaudit.",
"Tus laterales se meten por dentro: más control y ocasiones, pero sufres ante equipos de contraataque.":"Tes latéraux rentrent dans l'axe : plus de contrôle et d'occasions, mais tu souffres face aux équipes de contre-attaque.",
"Tus padres":"Tes parents",
"Tus padres cruzan medio mundo para verte jugar por primera vez desde que te fuiste al extranjero.":"Tes parents traversent la moitié du monde pour te voir jouer pour la première fois depuis ton départ à l'étranger.",
"Tus padres en la grada":"Tes parents en tribune",
"Tus padres vienen a pasar una semana contigo.":"Tes parents viennent passer une semaine avec toi.",
"Tus padres: {a} y {b}":"Tes parents : {a} et {b}",
"Tus palabras conectan con la afición y se vuelven virales.":"Tes mots trouvent écho chez les supporters et deviennent viraux.",
"Tus palabras emocionan y se hacen virales. Miles de jóvenes las comparten.":"Tes mots émeuvent et deviennent viraux. Des milliers de jeunes les partagent.",
"Tus palabras levantan a la plantilla y a la grada.":"Tes mots galvanisent l'effectif et les tribunes.",
"Tus palabras se citan en todos los medios y en los colegios.":"Tes mots sont cités dans tous les médias et dans les écoles.",
"Tus palabras suenan a excusa y la grada se enfada aún más.":"Tes mots sonnent comme des excuses et la tribune s'énerve encore plus.",
"Tus partidas":"Tes parties",
"Tus partidas, los nombres que escribes, el idioma elegido y el Salón de la fama se guardan en el almacenamiento local de tu dispositivo. Solo si publicas una gesta en GOAT LADDER se envían el alias y las estadísticas seleccionadas para mostrarlos en el ranking público.":"Tes sauvegardes, les noms saisis, la langue choisie et le Panthéon restent dans le stockage local de ton appareil. Seuls l'alias choisi et les statistiques sélectionnées sont envoyés pour le classement public si tu publies un exploit GOAT LADDER.",
"Tus partidos, fichajes y momentos clave":"Tes matchs, transferts et moments clés",
"Tus primas y tus condiciones son mucho peores que las de otras secciones del club y de la federación. Un grupo de compañeros prepara un escrito conjunto y te pide que lo firmes.":"Tes primes et tes conditions sont bien pires que celles des autres sections du club et de la fédération. Un groupe de coéquipiers prépare une lettre commune et te demande de la signer.",
"Tus rivalidades":"Tes rivalités",
"Tus récords":"Tes records",
"Tus trofeos de míster, con fecha y partido.":"Tes trophées d'entraîneur, avec date et match.",
"Tus vacaciones":"Tes vacances",
"Tus vacaciones son para descansar.":"Tes vacances, c'est fait pour se reposer.",
"Tus vecinos montan fiestas cada noche y no hay manera de dormir.":"Tes voisins font la fête tous les soirs et impossible de dormir.",
"Tutorial":"Tutoriel",
"TÚ":"TOI",
"TÚNEL":"TUNNEL",
