"Térmica de portero":"Sous-maillot de gardien",
"Térmica del cerrojo":"Sous-maillot du verrou",
"Térmica incombustible":"Sous-maillot infatigable",
"Térmica pro":"Sous-maillot pro",
"Térmicos de campo":"Thermiques de champ",
"Tírate a tiempo: para la barra en la zona verde":"Plonge à temps : arrête la barre dans la zone verte",
