"Tú a lo tuyo: entrenar y jugar.":"Chacun son affaire : t'entraîner et jouer.",
"Tú decides":"À toi de jouer",
"Tú decides fichajes, precios de las entradas, obras y presupuesto.":"Tu décides des transferts, du prix des billets, des travaux et du budget.",
"Tú decides las alineaciones. El dueño no lo olvidará.":"C'est toi qui fais les compos. Le patron ne l'oubliera pas.",
