"Well done, {name}. A deserved award, no doubt.":"Well done, {name}. A deserved award, no doubt.",
"What a career for {name}. Time to hang up the boots. Thanks for everything.":"Quelle carrière pour {name}. L'heure de raccrocher les crampons. Merci pour tout.",
"Y todavía había quien decía que íbamos a pelear arriba. JAJAJA 🤡":"Et il y en avait encore pour dire qu'on allait jouer le haut de tableau. MDR 🤡",
