"Ya agotaste el ultimátum en este club: si la confianza baja de {t}, te despiden.":"Tu as déjà épuisé l'ultimatum dans ce club : si la confiance passe sous {t}, tu es limogé.",
"Ya era hora de un golpe de timón. {name} nos da esperanza 🔥":"Il était temps de donner un coup de barre. {name} nous redonne espoir 🔥",
