"Ya negociasteis en este tramo.":"Vous avez déjà négocié durant cette période.",
"Ya ni me enfado, me da pena. Pena ajena de {club}.":"Je ne m'énerve même plus, ça me fait de la peine. Honte pour le {club}.",
"Ya no está en venta":"Plus à vendre",
"Ya no hay vuelta atrás.":"Il n'y a plus de retour en arrière possible.",
"Ya no os voy a defender más, {name}. Esto es insostenible.":"Je ne vais plus vous défendre, {name}. C'est intenable.",
"Ya se pueden callar unos cuantos. ¡{score}! 🤐":"Il y en a qui peuvent se taire maintenant. {score} ! 🤐",
