"{score}. Empate. Repartieron puntos como quien reparte tamales: uno pa' ti, uno pa' mí. 🫔":"{score}. Match nul. Ils se sont partagé les points comme on partage des tamales : un pour toi, un pour moi. 🫔",
"{score}. Esto en la NBA sería un «blowout» de los que se ven desde el banquillo con toalla al cuello. 🏀":"{score}. En NBA, ce serait un « blowout » de ceux qu'on regarde depuis le banc, serviette autour du cou. 🏀",
"{score}. Hay noches en las que el fútbol te pide quedarte callado y disfrutar. Esta es una. 🎙️":"{score}. Il y a des soirs où le football te demande de te taire et de profiter. Ce soir en est un. 🎙️",
"{score}. Lo bueno es que ya no se puede jugar peor. Lo malo es que siempre se puede. 📻":"{score}. La bonne nouvelle, c'est qu'on ne peut plus jouer plus mal. La mauvaise, c'est qu'on peut toujours. 📻",
"{score}. Lo que estamos viendo es historia, ¡HISTORIA! Que nadie diga que no lo avisé. 🤍👑":"{score}. Ce qu'on est en train de voir, c'est l'histoire, l'HISTOIRE ! Qu'on ne vienne pas dire que je ne l'avais pas annoncé. 🤍👑",
"{score}. Madre mía. MADRE MÍA. Esto no es normal, chat. El {club} está ON FIRE. 🔥":"{score}. Mon Dieu. MON DIEU. C'est pas normal, le chat. Le {club} est ON FIRE. 🔥",
"{score}. Mi abuela defiende mejor y tiene 87 años 👵":"{score}. Ma grand-mère défend mieux, et elle a 87 ans 👵",
"{score}. Ni fu ni fa. Un punto que sabe a poco… o a mucho, según se mire 🤷":"{score}. Ni chaud ni froid. Un point qui a un goût de trop peu… ou pas, selon le point de vue 🤷",
"{score}. Ojo, que esto hay que celebrarlo con calma… o sin calma. Buenas noches, el {club} vuela. 🌙":"{score}. Attention, il faut fêter ça avec calme… ou sans calme. Bonne nuit, le {club} s'envole. 🌙",
"{score}. Partido muy táctico, de ajedrez. Ninguno quiso arriesgar más de la cuenta. 🎧":"{score}. Match très tactique, une partie d'échecs. Personne n'a voulu prendre plus de risques que nécessaire. 🎧",
"{score}. SIN PALABRAS. Que alguien apague el estadio 🔦":"{score}. SANS VOIX. Que quelqu'un éteigne le stade 🔦",
"{score}. Vergüenza deportiva. Y lo voy a decir aunque me lluevan críticas. 🌶️":"{score}. Une honte sportive. Et je vais le dire même si les critiques pleuvent. 🌶️",
"{score}. Yo me voy a jugar al Fortnite, que ahí al menos reviven 🤪":"{score}. Je vais jouer à Fortnite, au moins là-bas on peut réanimer 🤪",
"{score}. ¡Esto es la Bombonera en mi living, loco! ¡Dale, dale! 💙💛":"{score}. C'est la Bombonera dans mon salon, mec ! Allez, allez ! 💙💛",
"{score}… Como exportero os digo: eso no es culpa de uno, es de todo el equipo. 🧤":"{score}… En tant qu'ancien gardien, je vous le dis : ce n'est pas la faute d'un seul, c'est toute l'équipe. 🧤",
"{score}… El vídeo de reacción de hoy va a ser corto y triste 🎬😢":"{score}… La vidéo réaction du jour va être courte et triste 🎬😢",
"{score}… Qué bajón, amigo. Hoy cierro el stream temprano 🐍💔":"{score}… Quel coup de mou, mec. Ce soir je coupe le stream tôt 🐍💔",
"{score}… con suerte. Que no se lo crean demasiado, que luego pasa lo que pasa.":"{score}… avec de la chance. Qu'ils ne s'enflamment pas trop, on sait comment ça finit.",
