"Última actualización: {d}":"Dernière mise à jour : {d}",
"Última hora":"Dernière minute",
"Última jornada: si ganan, son campeones. ¿Cómo lo vive?":"Dernière journée : en cas de victoire, vous êtes champions. Comment le vivez-vous ?",
"Último día de mercado":"Dernier jour du mercato",
"Último día de mercado. El {buyer} y el {club} han cerrado tu traspaso por {fee}, pero los papeles tienen que llegar a la liga antes de medianoche y quedan horas.":"Dernier jour du mercato. {buyer} et {club} ont bouclé ton transfert pour {fee}, mais les papiers doivent arriver à la ligue avant minuit et il reste quelques heures.",
"Último hombre":"Dernier défenseur",
"Último penalti de la tanda. Si marcas, campeón.":"Dernier tir au but de la séance. Si tu marques, vous êtes champions.",
"Últimos duelos":"Derniers duels",
"⏱️ Pitido final: {club} {score} {opp}. ¡Tres puntos!":"⏱️ Coup de sifflet final : {club} {score} {opp}. Trois points !",
"⏱️ Reparto de puntos: {club} {score} {opp}.":"⏱️ Partage des points : {club} {score} {opp}.",
